(function () {
  'use strict';
  // Multi-stage dividend discount model: one or two high-growth stages, then constant growth forever.
  //   D_t = D_(t-1) x (1 + g_stage)            for t = 1..N (N = stage 1 years + stage 2 years)
  //   PV(D_t) = D_t / (1 + r)^t
  //   Terminal value at year N (Gordon model): TV_N = D_N x (1 + g_T) / (r - g_T)   requires r > g_T
  //   P0 = sum PV(D_t) + TV_N / (1 + r)^N
  // Verified (scratch Node test): textbook supernormal-growth case D0 $1.15, 30% for 3 years then 8%,
  // r 13.4% -> D1 $1.4950, D2 $1.9435, D3 $2.5266, TV_3 $50.53, P0 $39.21. Two-stage check:
  // D0 $2.00, 20% for 3 years, 10% for 2 years, then 4%, r 12% -> P0 $42.53 (matches an independent
  // Python loop); with stage 2 at the terminal rate it equals the one-stage model ($38.88).
  // With both stage growths equal to g_T the price equals the constant-growth model D0(1+g)/(r-g).
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var money4 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 4, maximumFractionDigits: 4 });

  function num(id) {
    var el = document.getElementById(id);
    var v = el ? parseFloat(el.value) : NaN;
    return isNaN(v) ? NaN : v;
  }
  function pct(v) { return isFinite(v) ? (v * 100).toFixed(2) + '%' : '–'; }

  function value(d0, r, stages, gT) {
    var d = d0, t = 0, rows = [], pvDivs = 0;
    stages.forEach(function (s) {
      for (var i = 0; i < s.years; i++) {
        t++;
        d = d * (1 + s.g);
        var df = 1 / Math.pow(1 + r, t);
        rows.push({ year: t, g: s.g, div: d, df: df, pv: d * df });
        pvDivs += d * df;
      }
    });
    var tv = d * (1 + gT) / (r - gT);
    var pvTv = tv / Math.pow(1 + r, t);
    return { rows: rows, n: t, lastDiv: d, nextDiv: d * (1 + gT), tv: tv, pvTv: pvTv, pvDivs: pvDivs, price: pvDivs + pvTv };
  }

  var OUT = ['ncgPrice', 'ncgPvDivs', 'ncgPvTv', 'ncgTv', 'ncgShare', 'ncgNextDiv'];

  function clear() {
    OUT.forEach(function (id) { document.getElementById(id).textContent = '–'; });
    document.getElementById('ncgTable').innerHTML = '';
    document.getElementById('ncgFoot').innerHTML = '';
  }

  function update() {
    var two = document.getElementById('ncgStages').value === '2';
    document.getElementById('ncgStage2').hidden = !two;
    var d0 = num('ncgDividend'), r = num('ncgReturn') / 100, g1 = num('ncgG1') / 100, n1 = num('ncgN1'),
        g2 = num('ncgG2') / 100, n2 = num('ncgN2'), gT = num('ncgGT') / 100;
    var error = document.getElementById('ncgError');
    var msg = '';
    function badYears(n) { return isNaN(n) || n < 1 || n > 50 || n !== Math.floor(n); }
    function badG(g) { return isNaN(g) || g <= -1 || g > 5; }
    if (isNaN(d0) || d0 <= 0) msg = 'Enter a current dividend per share above 0.';
    else if (isNaN(r) || r <= -1 || r > 1) msg = 'Enter a required return above -100% and up to 100%.';
    else if (badG(g1)) msg = 'Stage 1 growth must be above -100% and up to 500%.';
    else if (badYears(n1)) msg = 'Stage 1 years must be a whole number from 1 to 50.';
    else if (two && badG(g2)) msg = 'Stage 2 growth must be above -100% and up to 500%.';
    else if (two && badYears(n2)) msg = 'Stage 2 years must be a whole number from 1 to 50.';
    else if (isNaN(gT) || gT <= -1) msg = 'Enter a long-term growth rate above -100%.';
    else if (!(r > gT)) msg = 'The required return must be higher than the long-term growth rate, or the terminal value has no finite answer.';
    var res = null;
    if (!msg) {
      var stages = [{ g: g1, years: n1 }];
      if (two) stages.push({ g: g2, years: n2 });
      res = value(d0, r, stages, gT);
      if (![res.price, res.tv, res.pvTv, res.pvDivs].every(isFinite) || Math.abs(res.price) > 1e12) msg = 'These inputs are too large to give a finite result.';
    }
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clear(); return; }

    document.getElementById('ncgPrice').textContent = money.format(res.price);
    document.getElementById('ncgPvDivs').textContent = money.format(res.pvDivs);
    document.getElementById('ncgPvTv').textContent = money.format(res.pvTv);
    document.getElementById('ncgTvLabel').textContent = 'Terminal value at end of year ' + res.n;
    document.getElementById('ncgTv').textContent = money.format(res.tv);
    document.getElementById('ncgShare').textContent = res.price > 0 ? pct(res.pvTv / res.price) : '–';
    document.getElementById('ncgNextDivLabel').textContent = 'First constant-growth dividend (year ' + (res.n + 1) + ')';
    document.getElementById('ncgNextDiv').textContent = money4.format(res.nextDiv);
    document.getElementById('ncgTable').innerHTML = res.rows.map(function (row) {
      return '<tr><td>' + row.year + '</td><td>' + pct(row.g) + '</td><td>' + money4.format(row.div) + '</td><td>' +
             row.df.toFixed(4) + '</td><td>' + money4.format(row.pv) + '</td></tr>';
    }).join('') +
      '<tr><td>' + res.n + ' (terminal)</td><td>' + pct(gT) + ' after</td><td>' + money4.format(res.tv) + '</td><td>' +
      (1 / Math.pow(1 + r, res.n)).toFixed(4) + '</td><td>' + money4.format(res.pvTv) + '</td></tr>';
    document.getElementById('ncgFoot').innerHTML = '<tr><th scope="row" colspan="4">Value per share (sum of present values)</th><td>' +
      money.format(res.price) + '</td></tr>';
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('ncgForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
